int foundry_fence_kind_find(const char *name) {
  static const char *const names[] = {"hedge", "iron", "living_willow", "low_wall", "picket", "rail", "reed", "split_rail", "stone_slab", "wattle"};
  for (int i = 0; name && i < 10; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

int foundry_fence_condition_find(const char *name) {
  static const char *const names[] = {"intact", "ruin"};
  for (int i = 0; name && i < 2; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

int foundry_fence_network_find(const char *name) {
  static const char *const names[] = {"bend_gentle", "bend_sharp", "branch", "compound", "cross", "paddocks", "ring", "slope", "star", "straight", "wye"};
  for (int i = 0; name && i < 11; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

int foundry_fence_season_find(const char *name) {
  static const char *const names[] = {"winter", "spring", "summer", "fall"};
  for (int i = 0; name && i < 4; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

int foundry_fence_detail_find(const char *name) {
  static const char *const names[] = {"high", "medium", "low"};
  for (int i = 0; name && i < 3; ++i)
    if (std::strcmp(names[i], name) == 0) return i;
  return -1;
}

foundry_status foundry_fence_start_door(foundry_runtime *rt, foundry_instance instance) {
  return foundry_status_of(rt->world.trigger(instance, &kType, 0));
}

foundry_status foundry_fence_get_result(foundry_runtime *rt, foundry_instance instance, foundry_fence_result *out) {
  uint32_t bits = 0;
  const runtime::Status st = rt->world.result(instance, bits);
  if (st != runtime::Status::ok) return foundry_status_of(st);
  if (!out) return FOUNDRY_OK;
  out->door_over = (bits & (1u << 0)) != 0;
  out->ready = (bits & runtime::World::kResultReady) != 0;
  return FOUNDRY_OK;
}

